mapper.select:
SELECT 
FROM post p
JOIN follow f ON f.target_id = p.member_id
JOIN member m ON m.id = p.member_id
JOIN post_image pi ON pi.post_id = p.id AND pi.image_order = 1

    AND f.member_id = #{memberId}
    AND p.subscriber_only = FALSE

        AND p.id < #{cursor}


ORDER BY p.id DESC
LIMIT #{limit}

SELECT 
FROM post p
JOIN subscription s ON s.creator_id = p.member_id
JOIN member m ON m.id = p.member_id
JOIN post_image pi ON pi.post_id = p.id AND pi.image_order = 1

    AND s.member_id = #{memberId}
    AND s.status = 'ACTIVE'


        AND p.id < #{cursor}


ORDER BY p.id DESC
LIMIT #{limit}
